#include <bits/stdc++.h>
using namespace std;
// Count how often push_back reallocates: capacity grows geometrically.
// Total time O(n) for n pushes (amortized O(1) each), space O(n).
int main() {
    vector<int> v;
    size_t lastCap = v.capacity();
    int reallocs = 0;
    long long copies = 0;            // elements moved during growth
    const int n = 1000;
    for (int i = 0; i < n; i++) {
        size_t before = v.size();
        v.push_back(i);
        if (v.capacity() != lastCap) {   // capacity changed => reallocation
            reallocs++;
            copies += before;            // old elements were moved over
            lastCap = v.capacity();
        }
    }
    cout << "pushes: " << n << "\n";
    cout << "reallocations: " << reallocs << "\n";
    cout << "elements copied in total: " << copies << "\n";
    cout << "copies per push: " << (double)copies / n << " (below 2)\n";
    // reserve removes reallocations entirely
    vector<int> w;
    w.reserve(n);
    size_t cap = w.capacity();
    for (int i = 0; i < n; i++) w.push_back(i);
    cout << "with reserve, capacity unchanged: " << (w.capacity() == cap) << "\n";
}

