// Show which containers keep element addresses stable when we insert more.
int main() {
    vector<int> v = {1, 2, 3};
    list<int> l = {1, 2, 3};
    deque<int> d = {1, 2, 3};
    // remember where the first element lives (we only compare, never dereference)
    uintptr_t pv = (uintptr_t)&v[0], pl = (uintptr_t)&l.front(), pd = (uintptr_t)&d[0];
    for (int i = 0; i < 1000; i++) {   // force vector reallocation
        v.push_back(i);
        l.push_back(i);
        d.push_back(i);
    }
    cout << "vector first element address unchanged: " << (pv == (uintptr_t)&v[0]) << "\n";
    cout << "list   first element address unchanged: " << (pl == (uintptr_t)&l.front()) << "\n";
    cout << "deque  first element address unchanged: " << (pd == (uintptr_t)&d[0]) << "\n";
    // Safe pattern: erase returns the next valid iterator
    vector<int> nums = {1, 2, 3, 4, 5, 6};
    for (auto it = nums.begin(); it != nums.end();) {
        if (*it % 2 == 0) it = nums.erase(it);  // do not use 'it' after erase
        else ++it;
    }
    cout << "after erasing evens:";
    for (int x : nums) cout << ' ' << x;
    cout << "\n";
}

