// list strengths: O(1) splice and erase through a held iterator, stable iterators.
int main() {
    list<string> tasks = {"a", "b", "c", "d"};
    auto itC = next(tasks.begin(), 2);          // iterator to "c"
    tasks.push_front("z");
    tasks.erase(next(tasks.begin()));            // erase "a" via iterator
    cout << "iterator still points to: " << *itC << "\n";
    // splice moves the node to the front without copying (O(1))
    tasks.splice(tasks.begin(), tasks, itC);
    cout << "after splice:";
    for (auto& s : tasks) cout << ' ' << s;
    cout << "\n";
    // vector middle insert shifts elements, but is often fast for small n
    vector<int> v(10000, 1);
    auto t0 = chrono::steady_clock::now();
    for (int i = 0; i < 1000; i++) v.insert(v.begin() + 5000, i);
    auto t1 = chrono::steady_clock::now();
    cout << "vector size after 1000 middle inserts: " << v.size() << "\n";
    cout << "(time varies by machine; measure before choosing)\n";
    (void)t0; (void)t1;
}

