// deque: blocks + map of block pointers. Emulate the index math with a tiny block size.
int main() {
    const int B = 4;               // slots per block (real ones: 512 bytes or more)
    int offset = 6;                // position of the first element inside the block map
    for (int i : {0, 1, 2, 5, 9}) {
        int pos = offset + i;
        cout << "element " << i << " -> block " << pos / B << ", slot " << pos % B << "\n";
    }
    // real deque: references stay valid on push_back / push_front
    deque<int> d = {10, 20, 30};
    int& first = d[0];
    for (int i = 0; i < 1000; i++) { d.push_back(i); d.push_front(-i); }
    cout << "reference to old first element still valid: " << first << "\n";
    cout << "d[1001] = " << d[1001] << " (random access, O(1))\n";
    cout << "size = " << d.size() << "\n";
}

