#include <bits/stdc++.h>
using namespace std;
// Watch buckets, load factor and rehashing as we insert.
int main() {
    unordered_map<int, int> m;
    size_t buckets = m.bucket_count();
    int rehashes = 0;
    for (int i = 0; i < 100; i++) {
        m[i] = i * i;
        if (m.bucket_count() != buckets) {           // table grew and relinked nodes
            rehashes++;
            cout << "size " << m.size() << ": buckets " << buckets << " -> "
                 << m.bucket_count() << "\n";
            buckets = m.bucket_count();
        }
    }
    cout << "rehashes: " << rehashes << "\n";
    cout << "load factor = " << m.load_factor() << " (max " << m.max_load_factor() << ")\n";
    unordered_map<int, int> r;
    r.reserve(100);                                  // pre-size: no rehash while inserting
    size_t b = r.bucket_count();
    for (int i = 0; i < 100; i++) r[i] = i;
    cout << "with reserve, bucket count unchanged: " << (b == r.bucket_count()) << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// pair<int,int> as an unordered_map key: provide hash + equality.
struct PairHash {
    size_t operator()(const pair<int, int>& p) const noexcept {
        // pack two 32-bit values into one 64-bit value, then hash it
        uint64_t packed = ((uint64_t)(uint32_t)p.first << 32) | (uint32_t)p.second;
        return hash<uint64_t>{}(packed);
    }
};
struct Point {
    int x, y;
    bool operator==(const Point&) const = default;    // C++20 equality
};
struct PointHash {
    size_t operator()(const Point& p) const noexcept {
        size_t h = hash<int>{}(p.x);
        h ^= hash<int>{}(p.y) + 0x9e3779b97f4a7c15ULL + (h << 6) + (h >> 2); // hash_combine
        return h;
    }
};
int main() {
    unordered_map<pair<int, int>, string, PairHash> grid;
    grid[{1, 2}] = "A";
    grid[{2, 1}] = "B";               // different key from (1,2)
    cout << "(1,2) -> " << grid[{1, 2}] << ", (2,1) -> " << grid[{2, 1}] << "\n";
    unordered_set<Point, PointHash> seen;
    seen.insert({3, 4});
    seen.insert({3, 4});              // duplicate ignored
    cout << "points stored: " << seen.size() << "\n";
    cout << "contains (4,3)? " << seen.count({4, 3}) << "\n";
}

#include <bits/stdc++.h>
using namespace std;
struct Job { string name; int deadline; };
int main() {
    priority_queue<int> maxHeap;                              // default: largest on top
    priority_queue<int, vector<int>, greater<int>> minHeap;   // smallest on top
    for (int x : {5, 1, 8, 3}) { maxHeap.push(x); minHeap.push(x); }
    cout << "input: 5 1 8 3\n";
    cout << "max-heap top: " << maxHeap.top() << ", min-heap top: " << minHeap.top() << "\n";
    // comparator returns true when a has LOWER priority than b
    auto cmp = [](const Job& a, const Job& b) { return a.deadline > b.deadline; };
    priority_queue<Job, vector<Job>, decltype(cmp)> jobs(cmp);
    jobs.push({"report", 9});
    jobs.push({"deploy", 2});
    jobs.push({"email", 5});
    cout << "earliest deadline first:";
    while (!jobs.empty()) {
        cout << ' ' << jobs.top().name << "(" << jobs.top().deadline << ")";
        jobs.pop();                                           // pop() returns void
    }
    cout << "\n";
    priority_queue<pair<int, int>> pq;                        // pairs compare lexicographically
    pq.push({2, 9}); pq.push({2, 11}); pq.push({1, 99});
    cout << "pair top: (" << pq.top().first << "," << pq.top().second << ")\n";
}

#include <bits/stdc++.h>
using namespace std;
// LRU cache: list keeps recency (front = newest), map finds the node in O(1).
class LRU {
    size_t cap;
    list<pair<int, int>> order;                                  // {key, value}
    unordered_map<int, list<pair<int, int>>::iterator> pos;
public:
    explicit LRU(size_t c) : cap(c) {}
    int get(int k) {
        auto it = pos.find(k);
        if (it == pos.end()) return -1;
        order.splice(order.begin(), order, it->second);          // move to front, O(1)
        return it->second->second;
    }
    void put(int k, int v) {
        auto it = pos.find(k);
        if (it != pos.end()) {
            it->second->second = v;
            order.splice(order.begin(), order, it->second);
            return;
        }
        if (order.size() == cap) {                               // evict least recent
            pos.erase(order.back().first);                       // key is stored in the node
            order.pop_back();
        }
        order.emplace_front(k, v);
        pos[k] = order.begin();
    }
};
int main() {
    LRU c(2);
    c.put(1, 100); c.put(2, 200);
    cout << "get(1) = " << c.get(1) << "\n";   // 1 is now most recent
    c.put(3, 300);                              // evicts key 2
    cout << "get(2) = " << c.get(2) << " (evicted)\n";
    cout << "get(3) = " << c.get(3) << "\n";
    c.put(4, 400);                              // evicts key 1
    cout << "get(1) = " << c.get(1) << " (evicted)\n";
    cout << "get(4) = " << c.get(4) << "\n";
}

