// A value type that announces constructions, so we can see what each call does.
struct V {
    int id;
    V() : id(0) { cout << "  default-construct\n"; }
    V(int i) : id(i) { cout << "  construct " << i << "\n"; }
    V(const V& o) : id(o.id) { cout << "  copy " << o.id << "\n"; }
    V(V&& o) noexcept : id(o.id) { cout << "  move " << o.id << "\n"; }
    V& operator=(const V& o) { id = o.id; cout << "  assign " << o.id << "\n"; return *this; }
    V& operator=(V&& o) noexcept { id = o.id; cout << "  move-assign " << o.id << "\n"; return *this; }
};
int main() {
    map<int, V> m;
    cout << "emplace(1, 10) new key:\n";   m.emplace(1, 10);
    cout << "emplace(1, 20) existing key (the standard allows a node to be built first):\n"; m.emplace(1, 20);
    cout << "try_emplace(1, 30) existing key (nothing constructed):\n";     m.try_emplace(1, 30);
    cout << "try_emplace(2, 40) new key:\n";                                m.try_emplace(2, 40);
    cout << "insert_or_assign(2, 50) existing key:\n";                      auto r = m.insert_or_assign(2, 50);
    cout << "  inserted new? " << r.second << "\n";
    cout << "operator[](3) missing key:\n"; m[3];
    cout << "final ids:";
    for (auto& [k, v] : m) cout << ' ' << k << "->" << v.id;
    cout << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// Associative containers treat a, b as equal when !cmp(a,b) && !cmp(b,a).
template <class C>
bool equivalent(C cmp, int a, int b) { return !cmp(a, b) && !cmp(b, a); }
struct Task { int priority; string name; };
int main() {
    auto lessEq = [](int a, int b) { return a <= b; };    // broken: cmp(x,x) is true
    auto less   = [](int a, int b) { return a < b; };     // strict weak ordering
    cout << "with <  : 5 equivalent to 5? " << equivalent(less, 5, 5) << "\n";
    cout << "with <= : 5 equivalent to 5? " << equivalent(lessEq, 5, 5)
         << "  (an element is not equal to itself, so find/erase fail)\n";
    // correct multi-field comparator: priority descending, then name ascending
    auto cmp = [](const Task& a, const Task& b) {
        if (a.priority != b.priority) return a.priority > b.priority;
        return a.name < b.name;
    };
    set<Task, decltype(cmp)> s(cmp);
    s.insert({1, "write"}); s.insert({3, "ship"}); s.insert({3, "build"}); s.insert({1, "write"});
    cout << "set size (duplicate rejected): " << s.size() << "\n";
    for (auto& t : s) cout << "  " << t.priority << " " << t.name << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// Anti-hash attack: keys that are all multiples of the bucket count collide.
struct SplitMix {
    static uint64_t mix(uint64_t x) {
        x += 0x9e3779b97f4a7c15ULL;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
        x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
        return x ^ (x >> 31);
    }
    size_t operator()(uint64_t x) const {
        static const uint64_t SEED = 88172645463325252ULL;  // use chrono::steady_clock in real code
        return mix(x + SEED);
    }
};
template <class M>
size_t longestChain(M& m) {
    size_t best = 0;
    for (size_t b = 0; b < m.bucket_count(); b++) best = max(best, m.bucket_size(b));
    return best;
}
int main() {
    const int n = 1000;
    unordered_map<long long, int> plain;
    plain.reserve(2 * n);
    size_t bc = plain.bucket_count();
    for (int i = 1; i <= n; i++) plain[(long long)i * bc] = i;   // all hit bucket 0
    cout << "identity hash, longest chain: " << longestChain(plain) << " of " << n << " keys\n";
    unordered_map<long long, int, SplitMix> safe;
    safe.reserve(2 * n);
    for (int i = 1; i <= n; i++) safe[(long long)i * bc] = i;
    cout << "splitmix64 hash, longest chain < 20: " << (longestChain(safe) < 20) << "\n";
    cout << "both tables hold " << plain.size() << " and " << safe.size() << " keys\n";
}

#include <bits/stdc++.h>
using namespace std;
// A tiny flat_map: two sorted vectors, binary search for lookup, O(n) insert.
struct FlatMap {
    vector<int> keys;
    vector<string> vals;
    void put(int k, const string& v) {
        auto it = lower_bound(keys.begin(), keys.end(), k);
        size_t i = it - keys.begin();
        if (it != keys.end() && *it == k) { vals[i] = v; return; }
        keys.insert(it, k);                    // shifts later keys: O(n)
        vals.insert(vals.begin() + i, v);
    }
    const string* get(int k) const {
        auto it = lower_bound(keys.begin(), keys.end(), k);   // O(log n), contiguous
        if (it == keys.end() || *it != k) return nullptr;
        return &vals[it - keys.begin()];
    }
};
int main() {
    FlatMap f;
    map<int, string> m;
    unordered_map<int, string> u;
    for (int k : {50, 10, 40, 20, 30}) {
        string v = "v" + to_string(k);
        f.put(k, v); m[k] = v; u[k] = v;
    }
    cout << "flat keys (sorted):";
    for (int k : f.keys) cout << ' ' << k;
    cout << "\n";
    for (int k : {30, 35}) {
        const string* p = f.get(k);
        cout << "lookup " << k << ": flat=" << (p ? *p : "none")
             << " map=" << (m.count(k) ? m[k] : "none")
             << " unordered=" << (u.count(k) ? u[k] : "none") << "\n";
    }
    cout << "map iteration order matches flat order: "
         << equal(f.keys.begin(), f.keys.end(), m.begin(), [](int a, auto& p) { return a == p.first; }) << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// RandomizedSet: vector gives random index, map gives value -> index. All O(1) average.
class RandomizedSet {
    vector<int> vals;
    unordered_map<int, size_t> idx;
    mt19937 rng{12345};                                  // fixed seed for repeatable output
public:
    bool insert(int x) {
        if (idx.count(x)) return false;
        idx[x] = vals.size();
        vals.push_back(x);
        return true;
    }
    bool erase(int x) {
        auto it = idx.find(x);
        if (it == idx.end()) return false;
        size_t i = it->second;
        int last = vals.back();
        vals[i] = last;                                  // move last element into the hole
        idx[last] = i;                                   // update BEFORE erasing (x may be last)
        vals.pop_back();
        idx.erase(x);
        return true;
    }
    int getRandom() {
        uniform_int_distribution<size_t> d(0, vals.size() - 1);
        return vals[d(rng)];
    }
    size_t size() const { return vals.size(); }
};
int main() {
    RandomizedSet s;
    for (int x : {10, 20, 30, 40}) s.insert(x);
    cout << "insert 20 again: " << s.insert(20) << "\n";
    cout << "erase 20: " << s.erase(20) << ", erase 99: " << s.erase(99) << "\n";
    cout << "erase last (40): " << s.erase(40) << ", size now " << s.size() << "\n";
    set<int> seen;
    for (int i = 0; i < 50; i++) seen.insert(s.getRandom());
    cout << "random values seen:";
    for (int x : seen) cout << ' ' << x;
    cout << "\n";
}
